def oxford_join_quoted(items):
    quoted = [f'"{i}"' for i in items]
    if not quoted:
        return ""
    if len(quoted) == 1:
        return quoted[0]
    if len(quoted) == 2:
        return f"{quoted[0]} and {quoted[1]}"
    return ", ".join(quoted[:-1]) + f", and {quoted[-1]}"

def oxford_join_semicolon(items):
    sep = ";" if any("," in i for i in items) else ","
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    joiner = sep + " "
    return joiner.join(items[:-1]) + f"{sep} and {items[-1]}"

def oxford_join_numbers(numbers):
    items = [str(n) for n in numbers]
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def oxford_join_empty_word(items, empty_word):
    if not items:
        return empty_word
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def wrap_double_quotes(s):
    escaped = s.replace('"', '\\"')
    return f'"{escaped}"'

def wrap_single_quotes(s):
    escaped = s.replace("'", "\\'")
    return f"'{escaped}'"

def quote_if_needed(s):
    if " " in s or "," in s:
        return f'"{s}"'
    return s

def csv_quote(s):
    if "," in s or '"' in s or "\n" in s:
        return '"' + s.replace('"', '""') + '"'
    return s
